</head>
<body class="bg-white text-slate-900 antialiased">
    <div id="root"></div>

    <script type="text/babel">
        const { useState, useEffect } = React;

        // --- Components ---

        const SkipLink = () => (
            <a href="#main-content" className="sr-only skip-link">
                Skip to main content
            </a>
        );

        const Header = () => {
            const [isMenuOpen, setIsMenuOpen] = useState(false);

            return (
                <header className="border-b border-slate-100 sticky top-0 bg-white/80 backdrop-blur-md z-40">
                    <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
                        <div className="flex justify-between items-center h-20">
                            {/* Logo */}
                            <div className="flex-shrink-0 flex items-center">
                                <a href="/" className="text-2xl font-bold tracking-tighter text-slate-900 focus:ring-2 focus:ring-slate-500 rounded-sm outline-none px-1" aria-current="page">LUMINA</a>
                            </div>

                            {/* Desktop Nav */}
                            <nav aria-label="Primary" className="hidden md:flex">
                                <ul className="flex space-x-10">
                                    <li><a href="#" className="text-sm font-semibold text-slate-600 hover:text-slate-900 transition-colors focus:ring-2 focus:ring-slate-500 rounded-sm outline-none px-1">Shop</a></li>
                                    <li><a href="#" className="text-sm font-semibold text-slate-600 hover:text-slate-900 transition-colors focus:ring-2 focus:ring-slate-500 rounded-sm outline-none px-1">Collections</a></li>
                                    <li><a href="#" className="text-sm font-semibold text-slate-600 hover:text-slate-900 transition-colors focus:ring-2 focus:ring-slate-500 rounded-sm outline-none px-1">About</a></li>
                                    <li><a href="#" className="text-sm font-semibold text-slate-600 hover:text-slate-900 transition-colors focus:ring-2 focus:ring-slate-500 rounded-sm outline-none px-1">Sustainability</a></li>
                                </ul>
                            </nav>

                            {/* Icons */}
                            <div className="flex items-center space-x-2">
                                <button aria-label="Search" className="p-2 text-slate-600 hover:text-slate-900 focus:ring-2 focus:ring-slate-500 rounded-full outline-none transition-colors">
                                    <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><circle cx="11" cy="11" r="8"></circle><line x1="21" y1="21" x2="16.65" y2="16.65"></line></svg>
                                </button>
                                <button aria-label="Account" className="p-2 text-slate-600 hover:text-slate-900 focus:ring-2 focus:ring-slate-500 rounded-full outline-none transition-colors">
                                    <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2"></path><circle cx="12" cy="7" r="4"></circle></svg>
                                </button>
                                <button aria-label="Cart, 0 items" className="p-2 text-slate-600 hover:text-slate-900 relative focus:ring-2 focus:ring-slate-500 rounded-full outline-none transition-colors">
                                    <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M6 2 3 6v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2V6l-3-4Z"></path><path d="M3 6h18"></path><path d="M16 10a4 4 0 0 1-8 0"></path></svg>
                                    <span className="absolute top-1 right-1 block h-4 w-4 rounded-full bg-slate-900 text-[10px] font-bold text-white text-center leading-4">0</span>
                                </button>
                                {/* Mobile Menu Toggle */}
                                <button 
                                    className="md:hidden p-2 text-slate-600 hover:text-slate-900 focus:ring-2 focus:ring-slate-500 rounded-md outline-none transition-colors"
                                    onClick={() => setIsMenuOpen(!isMenuOpen)}
                                    aria-expanded={isMenuOpen}
                                    aria-label="Toggle Menu"
                                >
                                    <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                                        {isMenuOpen ? (
                                            <React.Fragment>
                                                <line x1="18" y1="6" x2="6" y2="18"></line>
                                                <line x1="6" y1="6" x2="18" y2="18"></line>
                                            </React.Fragment>
                                        ) : (
                                            <React.Fragment>
                                                <line x1="3" y1="12" x2="21" y2="12"></line>
                                                <line x1="3" y1="6" x2="21" y2="6"></line>
                                                <line x1="3" y1="18" x2="21" y2="18"></line>
                                            </React.Fragment>
                                        )}
                                    </svg>
                                </button>
                            </div>
                        </div>
                    </div>

                    {/* Mobile Nav */}
                    {isMenuOpen && (
                        <nav className="md:hidden border-t border-slate-100 bg-white" aria-label="Mobile Navigation">
                            <ul className="px-4 pt-2 pb-6 space-y-2">
                                <li><a href="#" className="block py-3 text-base font-semibold text-slate-700 hover:text-slate-900 focus:ring-2 focus:ring-slate-500 rounded-md outline-none px-2">Shop</a></li>
                                <li><a href="#" className="block py-3 text-base font-semibold text-slate-700 hover:text-slate-900 focus:ring-2 focus:ring-slate-500 rounded-md outline-none px-2">Collections</a></li>
                                <li><a href="#" className="block py-3 text-base font-semibold text-slate-700 hover:text-slate-900 focus:ring-2 focus:ring-slate-500 rounded-md outline-none px-2">About</a></li>
                                <li><a href="#" className="block py-3 text-base font-semibold text-slate-700 hover:text-slate-900 focus:ring-2 focus:ring-slate-500 rounded-md outline-none px-2">Sustainability</a></li>
                            </ul>
                        </nav>
                    )}
                </header>
            );
        };

        const Hero = () => (
            <section className="relative bg-slate-50 overflow-hidden">
                <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
                    <div className="relative z-10 py-16 sm:py-24 lg:py-32 lg:w-1/2">
                        <h1 className="text-4xl font-extrabold tracking-tight text-slate-900 sm:text-5xl lg:text-6xl">
                            The Summer Light Collection
                        </h1>
                        <p className="mt-6 text-xl text-slate-600 max-w-lg">
                            Minimalist designs inspired by the gentle glow of Nordic summers. Bring warmth and clarity to your home.
                        </p>
                        <div className="mt-10">
                            <a href="#" className="inline-block bg-slate-900 border border-transparent py-4 px-10 text-center font-bold text-white hover:bg-slate-800 focus:ring-4 focus:ring-slate-300 outline-none transition-all">
                                Shop the Collection
                            </a>
                        </div>
                    </div>
                </div>
                {/* Decorative background element */}
                <div className="absolute inset-y-0 right-0 w-full lg:w-1/2 bg-slate-200 hidden lg:block">
                    <img 
                        src="https://images.unsplash.com/photo-1513506003901-1e6a229e2d15?auto=format&fit=crop&q=80&w=1200" 
                        alt="" 
                        className="w-full h-full object-cover"
                        aria-hidden="true"
                    />
                </div>
            </section>
        );

        const ProductCard = ({ name, price, originalPrice, image, id }) => (
            <article className="group relative flex flex-col bg-white rounded-xl p-2 pb-4 hover:shadow-lg transition-shadow border border-transparent hover:border-slate-100">
                <div className="aspect-square w-full overflow-hidden bg-slate-100 group-hover:opacity-75 transition-opacity rounded-lg relative">
                    <img 
                        src={image} 
                        alt="" 
                        className="h-full w-full object-cover object-center"
                        aria-hidden="true"
                    />
                    {originalPrice && (
                        <div className="absolute top-2 left-2 bg-white px-2 py-1 rounded text-[10px] font-bold uppercase tracking-widest text-slate-900 shadow-sm">
                            Sale
                        </div>
                    )}
                </div>
                <div className="mt-4 px-2 flex justify-between">
                    <div>
                        <h3 className="text-sm font-bold text-slate-900">
                            <a href={`/product/${id}`} className="rounded-sm focus:ring-2 focus:ring-slate-900 focus:ring-offset-2 outline-none">
                                <span aria-hidden="true" className="absolute inset-0 rounded-xl"></span>
                                {name}
                            </a>
                        </h3>
                        <div className="mt-1 text-sm text-slate-500 flex items-center gap-2 font-medium">
                            <span className={originalPrice ? "text-slate-900 font-bold" : ""}>${price}</span>
                            {originalPrice && <span className="text-xs line-through opacity-60">${originalPrice}</span>}
                        </div>
                    </div>
                </div>
                <div className="mt-4 px-2">
                    <button 
                        type="button" 
                        aria-label={`Add to cart: ${name}`}
                        className="relative w-full bg-slate-900 text-white py-2.5 px-4 text-xs font-bold hover:bg-slate-800 focus:ring-2 focus:ring-slate-900 focus:ring-offset-2 focus:outline-none z-10 transition-all rounded-md uppercase tracking-wider"
                        onClick={(e) => {
                            e.preventDefault();
                            alert(`Added ${name} to cart`);
                        }}
                    >
                        Add to Cart
                    </button>
                </div>
            </article>
        );

        const ProductGrid = ({ title, products }) => (
            <section className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-20" aria-labelledby={`${title.toLowerCase().replace(/\s+/g, '-')}-heading`}>
