        const Editorial = () => (
            <section className="bg-slate-900 text-white py-24 my-12">
                <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 flex flex-col lg:flex-row items-center gap-20">
                    <div className="lg:w-1/2">
                        <img 
                            src="https://images.unsplash.com/photo-1494438639946-1ebd1d20bf85?auto=format&fit=crop&q=80&w=1200" 
                            alt="A serene minimalist living room featuring Lumina furniture and warm lighting" 
                            className="w-full h-auto shadow-2xl rounded-xl"
